const CACHE='care-kotoba-icons-v1';
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/favicon.svg','/icon-192.png','/icon-512.png'])));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||u.pathname.startsWith('/api/'))return;if(['/favicon.svg','/icon-192.png','/icon-512.png'].includes(u.pathname)){e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request)));}else if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>new Response('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Care Kotoba</title><body style="background:#f8f9fc;color:#665573;font-family:system-ui;text-align:center;padding:25vh 24px"><h1 style="font-size:24px">また、一緒に話しましょう。</h1><p style="font-size:14px;line-height:2">練習にはインターネット接続が必要です。<br>接続を確認して、もう一度お試しください。</p><button onclick="location.reload()" style="background:#8970b9;color:white;border:0;border-radius:10px;padding:13px 24px">もう一度読み込む</button></body></html>',{headers:{'Content-Type':'text/html;charset=utf-8'}})));}});
